 for _, raw := range c.ScanTechniques {
  found := NotSupportTechnique
  for _, technique := range []ScanTechnique{TCPSYN,TCPConnect,TCPACK,TCPWindow,TCPMaimon,TCPNull,TCPFIN,TCPXmas} {
   if strings.EqualFold(raw, technique.String()) {found = technique; break}
  }
  scanTechniques = append(scanTechniques,found)
 }
 return
}

func (c PortScanConf) Validate() (errs []error) {
 if c.IsZero() {return nil}
 if c.ScannerBinPath == "" {errs = append(errs, fmt.Errorf("scannerBinPath is required"))} else if info, err := os.Stat(c.ScannerBinPath); err != nil || info.IsDir() || info.Mode()&0111 == 0 {
  errs = append(errs, fmt.Errorf("scannerBinPath must name an executable file: %s", c.ScannerBinPath))
 }
 techniques := c.GetScanTechniques()
 if len(techniques)>1 {errs=append(errs,fmt.Errorf("multiple scan techniques are unsupported"))}
 for _, technique := range techniques {
  if technique == NotSupportTechnique {errs=append(errs,fmt.Errorf("unsupported scan technique"))}
  if !c.HasPrivileged && technique != TCPConnect && technique != NotSupportTechnique {errs=append(errs,fmt.Errorf("scan technique requires privileges"))}
  if c.SourcePort != "" && technique == TCPConnect {errs=append(errs,fmt.Errorf("sourcePort is incompatible with TCP connect"))}
