// ValidateOnScan validates configuration
func (c Config) ValidateOnScan() bool {
	errs := c.checkSSHKeyExist()
	if len(c.ResultsDir) != 0 {
		if ok, _ := govalidator.IsFilePath(c.ResultsDir); !ok {
			errs = append(errs, xerrors.Errorf(
				"JSON base directory must be a *Absolute* file path. -results-dir: %s", c.ResultsDir))
		}
	}

	if _, err := govalidator.ValidateStruct(c); err != nil {
		errs = append(errs, err)
	}
	for name, server := range c.Servers {
		if server.Module.IsScanPort() && server.PortScan != nil {
			for _, err := range server.PortScan.Validate() {
				errs = append(errs, xerrors.Errorf("%s portscan: %w", name, err))
			}
		}
	}
	for _, err := range errs {
		logging.Log.Error(err)
	}
	return len(errs) == 0
}

func (c Config) checkSSHKeyExist() (errs []error) {
	for serverName, v := range c.Servers {
		if v.Type == constant.ServerTypePseudo {
			continue
		}
		if v.KeyPath != "" {
			if _, err := os.Stat(v.KeyPath); err != nil {
				errs = append(errs, xerrors.Errorf(
					"%s is invalid. keypath: %s not exists", serverName, v.KeyPath))
			}
		}
	}
	return errs
}
package config

import (
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

// ScanTechnique identifies an nmap TCP scan technique.
type ScanTechnique int

const (
	NotSupportTechnique ScanTechnique = iota
	TCPSYN
	TCPConnect
	TCPACK
	TCPWindow
	TCPMaimon
	TCPNull
	TCPFIN
	TCPXmas
)

func (s ScanTechnique) String() string {
	switch s {
	case TCPSYN:
		return "sS"
	case TCPConnect:
		return "sT"
	case TCPACK:
		return "sA"
	case TCPWindow:
		return "sW"
	case TCPMaimon:
		return "sM"
	case TCPNull:
		return "sN"
	case TCPFIN:
		return "sF"
	case TCPXmas:
		return "sX"
	default:
		return ""
	}
}

// PortScanConf configures nmap on the Vuls host.
type PortScanConf struct {
	ScannerBinPath       string   `toml:"scannerBinPath" json:"scannerBinPath,omitempty"`
	ScanTechniques       []string `toml:"scanTechniques" json:"scanTechniques,omitempty"`
	HasPrivileged        bool     `toml:"hasPrivileged" json:"hasPrivileged,omitempty"`
	SourcePort           string   `toml:"sourcePort" json:"sourcePort,omitempty"`
	IsUseExternalScanner bool     `toml:"-" json:"-"`
}

func (c PortScanConf) IsZero() bool {
	return c.ScannerBinPath == "" && len(c.ScanTechniques) == 0 && c.SourcePort == "" && !c.HasPrivileged
}

func (c *PortScanConf) GetScanTechniques() (scanTechniques []ScanTechnique) {
	for _, raw := range c.ScanTechniques {
		found := NotSupportTechnique
		for _, technique := range []ScanTechnique{TCPSYN, TCPConnect, TCPACK, TCPWindow, TCPMaimon, TCPNull, TCPFIN, TCPXmas} {
			if strings.EqualFold(raw, technique.String()) {
				found = technique
				break
			}
		}
		scanTechniques = append(scanTechniques, found)
	}
	return
}

func (c PortScanConf) Validate() (errs []error) {
	if c.IsZero() {
		return nil
	}
	if c.ScannerBinPath == "" {
		errs = append(errs, fmt.Errorf("scannerBinPath is required"))
	} else if info, err := os.Stat(c.ScannerBinPath); err != nil || info.IsDir() || info.Mode()&0111 == 0 {
		errs = append(errs, fmt.Errorf("scannerBinPath must name an executable file: %s", c.ScannerBinPath))
	}
	techniques := c.GetScanTechniques()
	if len(techniques) > 1 {
		errs = append(errs, fmt.Errorf("multiple scan techniques are unsupported"))
	}
	for _, technique := range techniques {
		if technique == NotSupportTechnique {
			errs = append(errs, fmt.Errorf("unsupported scan technique"))
		}
		if !c.HasPrivileged && technique != TCPConnect && technique != NotSupportTechnique {
			errs = append(errs, fmt.Errorf("scan technique requires privileges"))
		}
		if c.SourcePort != "" && technique == TCPConnect {
			errs = append(errs, fmt.Errorf("sourcePort is incompatible with TCP connect"))
		}
	}
	if c.SourcePort != "" && len(techniques) == 0 && !c.HasPrivileged {
		errs = append(errs, fmt.Errorf("sourcePort is incompatible with TCP connect"))
	}
	if c.SourcePort != "" {
		port, err := strconv.Atoi(c.SourcePort)
		if err != nil || port < 1 || port > 65535 {
			errs = append(errs, fmt.Errorf("sourcePort must be between 1 and 65535"))
		}
	}
	if c.HasPrivileged && os.Geteuid() != 0 && c.ScannerBinPath != "" {
		output, err := exec.Command("getcap", c.ScannerBinPath).CombinedOutput()
		if err != nil {
			errs = append(errs, fmt.Errorf("failed to check scanner capabilities: %v: %s", err, strings.TrimSpace(string(output))))
		} else if !strings.Contains(string(output), "cap_net_raw") || !strings.Contains(string(output), "+ep") {
			errs = append(errs, fmt.Errorf("scannerBinPath lacks valid cap_net_raw+ep capability data: %s", strings.TrimSpace(string(output))))
		}
	}
	return
}
package scanner

import (
	"encoding/xml"
	"fmt"
	"net"
	osexec "os/exec"
	"sort"
	"strconv"
	"strings"

	"github.com/future-architect/vuls/config"
)

func setScanTechniques(c *config.PortScanConf) ([]string, error) {
	techniques := c.GetScanTechniques()
	if len(techniques) > 1 {
		return nil, fmt.Errorf("multiple scan techniques are unsupported")
	}
	if len(techniques) == 0 {
		if c.HasPrivileged {
			return []string{"-sS"}, nil
		}
		return []string{"-sT"}, nil
	}
	if techniques[0] == config.NotSupportTechnique {
		return nil, fmt.Errorf("unsupported scan technique")
	}
	return []string{"-" + techniques[0].String()}, nil
}

func formatNmapOptionsToString(options []string) string { return strings.Join(options, " ") }

type nmapResult struct {
	Hosts []struct {
		Status struct {
			State string `xml:"state,attr"`
		} `xml:"status"`
		Addresses []struct {
			Addr string `xml:"addr,attr"`
		} `xml:"address"`
		Ports []struct {
			Protocol string `xml:"protocol,attr"`
			PortID   string `xml:"portid,attr"`
			State    struct {
				State string `xml:"state,attr"`
			} `xml:"state"`
		} `xml:"ports>port"`
	} `xml:"host"`
}

func (l *base) execExternalPortScan(dest map[string][]string) ([]string, error) {
	c := l.ServerInfo.PortScan
	if c == nil {
		return nil, fmt.Errorf("portscan configuration is missing")
	}
	if errs := c.Validate(); len(errs) > 0 {
		return nil, errs[0]
	}
	technique, err := setScanTechniques(c)
	if err != nil {
		return nil, err
	}
	var result []string
	ips := make([]string, 0, len(dest))
	for ip := range dest {
		ips = append(ips, ip)
	}
	sort.Strings(ips)
	for _, ip := range ips {
		if net.ParseIP(ip) == nil {
			return nil, fmt.Errorf("invalid scan destination: %s", ip)
		}
		if !isLocalExec(l.ServerInfo.Port, l.ServerInfo.Host) && net.ParseIP(ip).IsLoopback() {
			continue
		}
		ports := dest[ip]
		if len(ports) == 0 {
			continue
		}
		allowed := map[string]bool{}
		for _, p := range ports {
			n, e := strconv.Atoi(p)
			if e != nil || n < 1 || n > 65535 {
				return nil, fmt.Errorf("invalid scan port: %s", p)
			}
			allowed[p] = true
		}
		args := append([]string{}, technique...)
		args = append(args, "-Pn", "-n", "-oX", "-", "-p", strings.Join(ports, ","))
		if c.SourcePort != "" {
			args = append(args, "-g", c.SourcePort)
		}
		args = append(args, ip)
		output, err := osexec.Command(c.ScannerBinPath, args...).CombinedOutput()
		if err != nil {
			return nil, fmt.Errorf("nmap scan of %s failed (%s): %w: %s", ip, formatNmapOptionsToString(args), err, strings.TrimSpace(string(output)))
		}
		var parsed nmapResult
		if err := xml.Unmarshal(output, &parsed); err != nil {
			return nil, fmt.Errorf("invalid nmap XML for %s: %w", ip, err)
		}
		for _, host := range parsed.Hosts {
			if host.Status.State != "up" {
				continue
			}
			matches := false
			for _, addr := range host.Addresses {
				if addr.Addr == ip {
					matches = true
				}
			}
			if !matches {
				continue
			}
			for _, port := range host.Ports {
				if port.Protocol == "tcp" && port.State.State == "open" && allowed[port.PortID] {
					result = append(result, net.JoinHostPort(ip, port.PortID))
				}
			}
		}
	}
	return result, nil
}

